package com.bank.portal.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import lombok.*;
@Entity @Table(name="credit_cards",indexes=@Index(name="idx_card_customer",columnList="customer_id")) @Getter @Setter @NoArgsConstructor public class CreditCard extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="customer_id") private Customer customer; @Column(nullable=false,unique=true,length=19) private String cardNumber; @Enumerated(EnumType.STRING) @Column(nullable=false) private CardType cardType; @Column(nullable=false,precision=15,scale=2) private BigDecimal creditLimit; @Column(nullable=false,precision=15,scale=2) private BigDecimal availableCredit; @Column(nullable=false,precision=15,scale=2) private BigDecimal outstandingAmount; @Column(nullable=false) private LocalDate expiryDate; @Enumerated(EnumType.STRING) @Column(nullable=false) private CardStatus status; }
